def same_chars(s0: str, s1: str) -> bool:
    from collections import Counter

    counter0 = Counter(s0)
    counter1 = Counter(s1)

    return counter0.keys() == counter1.keys() and all(counter0[char] == counter1[char] for char in counter0)

